def _components(grid, color):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = set()
            while q:
                x, y = q.pop()
                cells.add((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (x + dx, y + dy)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        q.append(p)
            result.append(cells)
    return result


def _variants(cells):
    r0, c0 = min(r for r, c in cells), min(c for r, c in cells)
    pts = [(r-r0, c-c0) for r, c in cells]
    out = []
    for flip in (1, -1):
        for k in range(4):
            p = []
            for r, c in pts:
                x, y = r, flip*c
                for _ in range(k):
                    x, y = y, -x
                p.append((x, y))
            a, b = min(x for x, y in p), min(y for x, y in p)
            out.append(frozenset((x-a, y-b) for x, y in p))
    return out


def _same_shape(a, b):
    return len(a) == len(b) and bool(set(_variants(a)) & set(_variants(b)))


def _contains_shape(container, shape):
    if len(shape) > len(container):
        return False
    for v in _variants(shape):
        mh, mw = max(r for r, c in v), max(c for r, c in v)
        for r in range(min(x for x, y in container), max(x for x, y in container)-mh+1):
            for c in range(min(y for x, y in container), max(y for x, y in container)-mw+1):
                if all((r+x, c+y) in container for x, y in v):
                    return True
    return False


def _is_l(cells):
    rs = [r for r, c in cells]
    cs = [c for r, c in cells]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    h, w = r1-r0+1, c1-c0+1
    if min(h, w) < 4:
        return False
    expected = set()
    for c in range(c0, c1+1):
        expected.add((r0, c))
        expected.add((r1, c))
    for r in range(r0, r1+1):
        expected.add((r, c0))
        expected.add((r, c1))
    # Any orientation of an L made from two full perpendicular sides.
    return cells in (expected,)


