    g = [row[:] for row in grid]
    counts = Counter(v for row in g for v in row)
    background = counts.most_common(1)[0][0]
    by_color = {col: _components(g, col) for col in counts}

    markers = []
    for col, comps in by_color.items():
        if col == background:
            continue
        for comp in comps:
            if _is_l(comp):
                markers.append((col, comp))
    if not markers:
        return g
    marker_color, marker = max(markers, key=lambda x: len(x[1]))

    comps = []
    for col, groups in by_color.items():
        if col in (background, marker_color):
            continue
        for comp in groups:
            comps.append((col, comp))

    # A standalone object that duplicates a shape embedded in another object.
    contained = []
    for i, (col, obj) in enumerate(comps):
        for j, (other_col, other) in enumerate(comps):
            if i != j and col == other_col and len(other) > len(obj) and _contains_shape(other, obj):
                contained.append((obj, col))
                break
    if contained:
        # The repeated small object is the one outside the larger compound object.
        target, _ = max(contained, key=lambda x: len(x[0]))
    else:
        pairs = []
        for i, (ca, a) in enumerate(comps):
            for cb, b in comps[i+1:]:
                if _same_shape(a, b):
                    pairs.append((ca, a, cb, b))
        if not pairs:
            return g
        # Recolor the copy belonging to the more prevalent color, leaving the rarer
        # copy as the shape exemplar.
        ca, a, cb, b = max(pairs, key=lambda p: (counts[p[0]] + counts[p[2]], min(len(p[1]), len(p[3]))))
        if counts[ca] >= counts[cb]:
            target = a
        else:
            target = b

    for r, c in target:
        g[r][c] = marker_color
    return g
